// The three residue classes of 3 (mod 4) among the integers 0 to 11,
// as vertical stacks over the residues they occupy.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,240);
for (int k = 0; k < 3; ++k) {
  dot((20+40*k,0), black+3.5pt);
  dot((20+40*k,-30), black+3.5pt);
  dot((20+40*k,-60), black+3.5pt);
}
for (int k = 0; k < 3; ++k) {
  dot((140+40*k,0), black+3.5pt);
  dot((140+40*k,-30), black+3.5pt);
  dot((140+40*k,-60), black+3.5pt);
}
label("$0$",(20,8),N);
label("$4$",(20,-68),S);
label("$8$",(20,8),N);
label("$1$",(60,8),N);
label("$5$",(60,-68),S);
label("$9$",(60,8),N);
label("$2$",(100,8),N);
label("$6$",(100,-68),S);
label("$10$",(100,8),N);
label("$3$",(140,8),N);
label("$7$",(140,-68),S);
label("$11$",(140,8),N);

// The Chinese Remainder Theorem as a table: for moduli 4 and 7, one row per
// candidate remainder of 4 and one column per remainder of 7, with the
// surviving cell highlighted.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,240);
for (int r = 0; r < 3; ++r) {
  for (int c = 0; c < 4; ++c) {
    label("$"+string(3+4*r)+"$",(20+60*c,-40*r),NW);
    label("$"+string(2+7*c)+"$",(20+60*c,8),NW);
  }
}
draw((14,-8)--(250,-8));
dot((20,-40), black+4pt);
label("the one number meeting both conditions",(120,70),N);

// The multiplicative order of 3 modulo 8: successive powers cycle with
// period 2, which is the reason an inverse or a residue problem terminates.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,220);
dot((20,0), black+4pt);
dot((120,0), black+4pt);
draw((28,2)--(112,2),Arrow);
draw((112,10)--(28,10),Arrow);
label("$3$",(20,20),S);
label("$1$",(120,20),S);
label("multiplying by $3$ again returns to the first residue",(70,70),N);
dot((20,-90), black+4pt);
dot((120,-90), black+4pt);
draw((28,-88)--(112,-88),Arrow);
draw((112,-96)--(28,-96),Arrow);
label("$3$",(20,-70),N);
label("$9 \\equiv 1$",(120,-70),N);
label("so $3^{2} \\equiv 1 \\pmod{8}$ and the order of $3$ is $2$",(70,-140),N);
